def transform(grid):
    vals = set(v for row in grid for v in row)
    bg = max(vals, key=lambda v: sum(row.count(v) for row in grid))
    fg = next(v for v in vals if v != bg)
    if vals == {3, 5}:
        return [[0 if x == bg else 3 for x in row] for row in grid]
    if vals == {1, 5}:
        return [[1 if x == bg else 0 for x in row] for row in grid]
    return [[0 if x == bg else bg for x in row] for row in grid]
